-- =============================================================================================
-- EstateOps database. PostgreSQL 15 or newer (also runs on 14).
-- One schema per service. No foreign keys across schemas: services share ids and events, never
-- tables. Safe to run more than once (IF NOT EXISTS, upserts for reference data).
--
-- Conventions
--   * id uuid generated by the application. tenant_id on every business row, first in indexes.
--   * Money is bigint minor units + char(3) currency. Never numeric or float.
--   * Enums are text + CHECK so adding a value is a one-line change.
--   * version int is the optimistic-lock counter on aggregates that staff edit.
--   * Every schema has outbox, processed_event, idempotency_key and an append-only audit_log.
--
-- Run:  psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f db/estateops.sql
-- =============================================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS identity;
CREATE SCHEMA IF NOT EXISTS inventory;
CREATE SCHEMA IF NOT EXISTS customer;
CREATE SCHEMA IF NOT EXISTS sales;
CREATE SCHEMA IF NOT EXISTS billing;
CREATE SCHEMA IF NOT EXISTS contract;

-- Fuzzy search (unit number, customer name). Optional: the file still runs without it.
DO $$
BEGIN
  CREATE EXTENSION IF NOT EXISTS pg_trgm;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'pg_trgm is not available; text search will use plain indexes';
END $$;

-- ---------------------------------------------------------------------------------------------
-- Shared tables, created once per schema
-- ---------------------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.estateops_forbid_change() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'audit_log is append-only';
END;
$$ LANGUAGE plpgsql;

DO $$
DECLARE
  s text;
BEGIN
  FOREACH s IN ARRAY ARRAY['identity', 'inventory', 'customer', 'sales', 'billing', 'contract'] LOOP
    -- Transactional outbox: written in the same transaction as the data, relayed afterwards.
    EXECUTE format($f$
      CREATE TABLE IF NOT EXISTS %1$I.outbox (
        id              uuid PRIMARY KEY,
        tenant_id       uuid        NOT NULL,
        type            text        NOT NULL,
        payload         jsonb       NOT NULL,
        status          text        NOT NULL DEFAULT 'pending'
                        CONSTRAINT outbox_status_chk CHECK (status IN ('pending', 'published', 'dead')),
        attempts        int         NOT NULL DEFAULT 0 CONSTRAINT outbox_attempts_chk CHECK (attempts >= 0),
        delivered_to    text[]      NOT NULL DEFAULT '{}',
        next_attempt_at timestamptz NOT NULL DEFAULT now(),
        last_error      text,
        created_at      timestamptz NOT NULL DEFAULT now(),
        published_at    timestamptz
      )$f$, s);
    EXECUTE format('CREATE INDEX IF NOT EXISTS outbox_pending_idx ON %1$I.outbox (next_attempt_at, created_at) WHERE status = ''pending''', s);

    -- Events already applied by this service, so a redelivered event changes nothing.
    EXECUTE format($f$
      CREATE TABLE IF NOT EXISTS %1$I.processed_event (
        event_id     uuid PRIMARY KEY,
        processed_at timestamptz NOT NULL DEFAULT now()
      )$f$, s);

    -- Stored responses for Idempotency-Key replays.
    EXECUTE format($f$
      CREATE TABLE IF NOT EXISTS %1$I.idempotency_key (
        tenant_id    uuid        NOT NULL,
        key          text        NOT NULL,
        route        text        NOT NULL,
        request_hash text        NOT NULL,
        status       int         NOT NULL,
        body         jsonb,
        created_at   timestamptz NOT NULL DEFAULT now(),
        PRIMARY KEY (tenant_id, key, route)
      )$f$, s);
    EXECUTE format('CREATE INDEX IF NOT EXISTS idempotency_key_age_idx ON %1$I.idempotency_key (created_at)', s);

    -- Append-only audit trail: who did what, with before and after.
    EXECUTE format($f$
      CREATE TABLE IF NOT EXISTS %1$I.audit_log (
        id           uuid PRIMARY KEY,
        tenant_id    uuid        NOT NULL,
        actor_id     uuid,
        actor_name   text,
        action       text        NOT NULL,
        subject_type text        NOT NULL,
        subject_id   text        NOT NULL,
        before       jsonb,
        after        jsonb,
        created_at   timestamptz NOT NULL DEFAULT now()
      )$f$, s);
    EXECUTE format('CREATE INDEX IF NOT EXISTS audit_subject_idx ON %1$I.audit_log (tenant_id, subject_type, subject_id, created_at DESC)', s);
    EXECUTE format('CREATE INDEX IF NOT EXISTS audit_time_idx ON %1$I.audit_log (tenant_id, created_at DESC)', s);
    EXECUTE format('CREATE OR REPLACE TRIGGER audit_log_append_only BEFORE UPDATE OR DELETE ON %1$I.audit_log FOR EACH ROW EXECUTE FUNCTION public.estateops_forbid_change()', s);
  END LOOP;
END $$;

-- =============================================================================================
-- identity: tenants, staff accounts, roles, permissions, sessions
-- =============================================================================================
CREATE TABLE IF NOT EXISTS identity.tenant (
  id         uuid PRIMARY KEY,
  slug       text        NOT NULL CONSTRAINT tenant_slug_chk CHECK (slug ~ '^[a-z][a-z0-9]{1,23}$'),
  name       text        NOT NULL,
  currency   char(3)     NOT NULL,
  locale     text        NOT NULL,
  time_zone  text        NOT NULL,
  area_unit  text        NOT NULL CONSTRAINT tenant_area_unit_chk CHECK (area_unit IN ('marla', 'kanal', 'sq_ft', 'sq_yd', 'sq_m')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version    int         NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS tenant_slug_uq ON identity.tenant (lower(slug));

-- Permission catalogue (reference data, upserted at the bottom of this file).
CREATE TABLE IF NOT EXISTS identity.permission (
  key        text PRIMARY KEY,
  grp        text NOT NULL,
  sort_order int  NOT NULL
);

CREATE TABLE IF NOT EXISTS identity.app_user (
  id            uuid PRIMARY KEY,
  tenant_id     uuid        NOT NULL REFERENCES identity.tenant (id) ON DELETE RESTRICT,
  email         text        NOT NULL,
  name          text        NOT NULL,
  role          text        NOT NULL CONSTRAINT app_user_role_chk CHECK (role IN
                  ('owner', 'admin', 'sales_manager', 'sales_agent', 'finance', 'inventory_manager',
                   'dealer_manager', 'support', 'marketing', 'auditor')),
  password_hash text        NOT NULL,
  totp_secret   text        NOT NULL,
  active        boolean     NOT NULL DEFAULT true,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  version       int         NOT NULL DEFAULT 1
);
-- Sign-in is by email alone, so an email belongs to exactly one account.
CREATE UNIQUE INDEX IF NOT EXISTS app_user_email_uq ON identity.app_user (lower(email));
CREATE INDEX IF NOT EXISTS app_user_tenant_idx ON identity.app_user (tenant_id, role);

CREATE TABLE IF NOT EXISTS identity.role_permission (
  tenant_id      uuid NOT NULL REFERENCES identity.tenant (id) ON DELETE RESTRICT,
  role           text NOT NULL CONSTRAINT role_permission_role_chk CHECK (role IN
                   ('owner', 'admin', 'sales_manager', 'sales_agent', 'finance', 'inventory_manager',
                    'dealer_manager', 'support', 'marketing', 'auditor')),
  permission_key text NOT NULL REFERENCES identity.permission (key) ON DELETE RESTRICT,
  PRIMARY KEY (tenant_id, role, permission_key)
);

-- Short-lived step between password and verification code.
CREATE TABLE IF NOT EXISTS identity.mfa_challenge (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  user_id    uuid        NOT NULL REFERENCES identity.app_user (id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL,
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS mfa_challenge_user_idx ON identity.mfa_challenge (user_id);

CREATE TABLE IF NOT EXISTS identity.refresh_token (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  user_id    uuid        NOT NULL REFERENCES identity.app_user (id) ON DELETE CASCADE,
  token_hash text        NOT NULL,
  expires_at timestamptz NOT NULL,
  used_at    timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS refresh_token_hash_uq ON identity.refresh_token (token_hash);
CREATE INDEX IF NOT EXISTS refresh_token_user_idx ON identity.refresh_token (user_id);

CREATE TABLE IF NOT EXISTS identity.login_history (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  user_id    uuid        NOT NULL REFERENCES identity.app_user (id) ON DELETE CASCADE,
  method     text        NOT NULL CONSTRAINT login_method_chk CHECK (method IN ('password', '2fa')),
  success    boolean     NOT NULL,
  ip         text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS login_history_user_idx ON identity.login_history (tenant_id, user_id, created_at DESC);

-- =============================================================================================
-- inventory: projects, structure, units
-- =============================================================================================
CREATE TABLE IF NOT EXISTS inventory.tenant_ref (
  tenant_id  uuid PRIMARY KEY,
  slug       text        NOT NULL,
  name       text        NOT NULL,
  currency   char(3)     NOT NULL,
  locale     text        NOT NULL,
  time_zone  text        NOT NULL,
  area_unit  text        NOT NULL,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS inventory.project (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  name       text        NOT NULL,
  location   text        NOT NULL DEFAULT '',
  kind       text        NOT NULL CONSTRAINT project_kind_chk CHECK (kind IN ('plot_society', 'tower', 'mixed')),
  created_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version    int         NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS project_name_uq ON inventory.project (tenant_id, lower(name));

CREATE TABLE IF NOT EXISTS inventory.phase (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  project_id uuid        NOT NULL REFERENCES inventory.project (id) ON DELETE RESTRICT,
  name       text        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS phase_name_uq ON inventory.phase (project_id, lower(name));

CREATE TABLE IF NOT EXISTS inventory.block (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  project_id uuid        NOT NULL REFERENCES inventory.project (id) ON DELETE RESTRICT,
  phase_id   uuid        REFERENCES inventory.phase (id) ON DELETE RESTRICT,
  name       text        NOT NULL,
  kind       text        NOT NULL CONSTRAINT block_kind_chk CHECK (kind IN ('plot_block', 'building')),
  geometry   jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS block_name_uq ON inventory.block (project_id, lower(name));

CREATE TABLE IF NOT EXISTS inventory.floor (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  block_id   uuid        NOT NULL REFERENCES inventory.block (id) ON DELETE RESTRICT,
  number     int         NOT NULL,
  label      text        NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT floor_block_number_uq UNIQUE (block_id, number)
);

CREATE TABLE IF NOT EXISTS inventory.unit (
  id           uuid PRIMARY KEY,
  tenant_id    uuid          NOT NULL,
  project_id   uuid          NOT NULL REFERENCES inventory.project (id) ON DELETE RESTRICT,
  phase_id     uuid          REFERENCES inventory.phase (id) ON DELETE RESTRICT,
  block_id     uuid          REFERENCES inventory.block (id) ON DELETE RESTRICT,
  floor_id     uuid          REFERENCES inventory.floor (id) ON DELETE RESTRICT,
  unit_no      text          NOT NULL,
  kind         text          NOT NULL CONSTRAINT unit_kind_chk CHECK (kind IN ('plot', 'flat', 'villa', 'shop')),
  area_value   numeric(14,2) NOT NULL CONSTRAINT unit_area_chk CHECK (area_value > 0),
  area_unit    text          NOT NULL CONSTRAINT unit_area_unit_chk CHECK (area_unit IN ('marla', 'kanal', 'sq_ft', 'sq_yd', 'sq_m')),
  bedrooms     int           CONSTRAINT unit_bedrooms_chk CHECK (bedrooms IS NULL OR bedrooms >= 0),
  facing       text,
  view         text,
  corner       boolean       NOT NULL DEFAULT false,
  parking      int           NOT NULL DEFAULT 0 CONSTRAINT unit_parking_chk CHECK (parking >= 0),
  attributes   jsonb         NOT NULL DEFAULT '{}',
  status       text          NOT NULL DEFAULT 'available' CONSTRAINT unit_status_chk CHECK (status IN
                 ('available', 'held', 'booked', 'sold', 'blocked')),
  list_price   bigint        NOT NULL CONSTRAINT unit_price_chk CHECK (list_price >= 0),
  currency     char(3)       NOT NULL,
  geometry     jsonb,
  booking_id   uuid,         -- reference to sales.booking, no foreign key across schemas
  ever_booked  boolean       NOT NULL DEFAULT false,
  created_by   uuid,
  created_at   timestamptz   NOT NULL DEFAULT now(),
  updated_at   timestamptz   NOT NULL DEFAULT now(),
  version      int           NOT NULL DEFAULT 1,
  -- a unit with a booking is booked or sold, never available
  CONSTRAINT unit_booking_status_chk CHECK (booking_id IS NULL OR status IN ('booked', 'sold'))
);
CREATE UNIQUE INDEX IF NOT EXISTS unit_no_uq ON inventory.unit (tenant_id, project_id, lower(unit_no));
CREATE INDEX IF NOT EXISTS unit_project_status_idx ON inventory.unit (tenant_id, project_id, status, kind);
CREATE INDEX IF NOT EXISTS unit_status_idx ON inventory.unit (tenant_id, status);
CREATE INDEX IF NOT EXISTS unit_kind_idx ON inventory.unit (tenant_id, kind);
CREATE INDEX IF NOT EXISTS unit_page_idx ON inventory.unit (tenant_id, unit_no, id);

CREATE TABLE IF NOT EXISTS inventory.unit_status_history (
  id              uuid PRIMARY KEY,
  tenant_id       uuid        NOT NULL,
  unit_id         uuid        NOT NULL REFERENCES inventory.unit (id) ON DELETE RESTRICT,
  status          text        NOT NULL CONSTRAINT unit_history_status_chk CHECK (status IN
                    ('available', 'held', 'booked', 'sold', 'blocked')),
  changed_by      uuid,
  changed_by_name text,
  changed_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS unit_history_idx ON inventory.unit_status_history (unit_id, changed_at);

CREATE TABLE IF NOT EXISTS inventory.unit_media (
  id         uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  unit_id    uuid        NOT NULL REFERENCES inventory.unit (id) ON DELETE CASCADE,
  kind       text        NOT NULL CONSTRAINT unit_media_kind_chk CHECK (kind IN ('image', 'floor_plan')),
  url        text        NOT NULL,
  caption    text,
  sort_order int         NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS unit_media_unit_idx ON inventory.unit_media (unit_id, sort_order);

-- =============================================================================================
-- customer: buyers and their combined money position
-- =============================================================================================
CREATE TABLE IF NOT EXISTS customer.tenant_ref (
  tenant_id  uuid PRIMARY KEY,
  currency   char(3)     NOT NULL,
  source_at  timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS customer.customer (
  id                 uuid PRIMARY KEY,
  tenant_id          uuid        NOT NULL,
  full_name          text        NOT NULL,
  phone              text,
  email              text,
  id_number          text,
  city               text,
  preferred_language text        NOT NULL DEFAULT 'en',
  bookings_count     int         NOT NULL DEFAULT 0 CONSTRAINT customer_bookings_chk CHECK (bookings_count >= 0),
  total_value        bigint      NOT NULL DEFAULT 0,
  received_amount    bigint      NOT NULL DEFAULT 0,
  pending_amount     bigint      NOT NULL DEFAULT 0,
  overdue_amount     bigint      NOT NULL DEFAULT 0,
  escalated_count    int         NOT NULL DEFAULT 0,
  units_summary      text[]      NOT NULL DEFAULT '{}',
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  version            int         NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS customer_email_uq ON customer.customer (tenant_id, lower(email)) WHERE email IS NOT NULL;
CREATE INDEX IF NOT EXISTS customer_name_idx ON customer.customer (tenant_id, lower(full_name), id);
CREATE INDEX IF NOT EXISTS customer_overdue_idx ON customer.customer (tenant_id, overdue_amount) WHERE overdue_amount > 0;

CREATE TABLE IF NOT EXISTS customer.booking_summary (
  booking_id      uuid PRIMARY KEY,
  tenant_id       uuid        NOT NULL,
  customer_id     uuid        NOT NULL REFERENCES customer.customer (id) ON DELETE RESTRICT,
  unit_no         text        NOT NULL,
  total_price     bigint      NOT NULL,
  currency        char(3)     NOT NULL,
  received_amount bigint      NOT NULL DEFAULT 0,
  pending_amount  bigint      NOT NULL DEFAULT 0,
  overdue_amount  bigint      NOT NULL DEFAULT 0,
  escalated       boolean     NOT NULL DEFAULT false,
  cancelled       boolean     NOT NULL DEFAULT false,
  seq             int         NOT NULL DEFAULT 0,
  updated_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS booking_summary_customer_idx ON customer.booking_summary (tenant_id, customer_id);

-- =============================================================================================
-- sales: payment plans and bookings
-- =============================================================================================
CREATE TABLE IF NOT EXISTS sales.customer_ref (
  customer_id uuid PRIMARY KEY,
  tenant_id   uuid        NOT NULL,
  full_name   text        NOT NULL,
  phone       text,
  email       text,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS sales.unit_ref (
  unit_id      uuid PRIMARY KEY,
  tenant_id    uuid        NOT NULL,
  project_id   uuid        NOT NULL,
  project_name text        NOT NULL,
  unit_no      text        NOT NULL,
  kind         text        NOT NULL,
  status       text        NOT NULL,
  list_price   bigint      NOT NULL,
  currency     char(3)     NOT NULL,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS sales_unit_ref_tenant_idx ON sales.unit_ref (tenant_id, project_id);

CREATE TABLE IF NOT EXISTS sales.payment_plan (
  id                uuid PRIMARY KEY,
  tenant_id         uuid        NOT NULL,
  name              text        NOT NULL,
  down_pct          int         NOT NULL CONSTRAINT plan_down_pct_chk CHECK (down_pct BETWEEN 0 AND 100),
  installment_count int         NOT NULL CONSTRAINT plan_count_chk CHECK (installment_count BETWEEN 1 AND 120),
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           int         NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS plan_name_uq ON sales.payment_plan (tenant_id, lower(name));

CREATE TABLE IF NOT EXISTS sales.booking (
  id                    uuid PRIMARY KEY,
  tenant_id             uuid        NOT NULL,
  unit_id               uuid        NOT NULL,
  customer_id           uuid        NOT NULL,
  plan_id               uuid        NOT NULL REFERENCES sales.payment_plan (id) ON DELETE RESTRICT,
  plan_name             text        NOT NULL,
  down_pct              int         NOT NULL,
  installment_count     int         NOT NULL,
  status                text        NOT NULL DEFAULT 'requested' CONSTRAINT booking_status_chk CHECK (status IN
                          ('requested', 'confirmed', 'active', 'completed', 'cancelled')),
  total_price           bigint      NOT NULL CONSTRAINT booking_price_chk CHECK (total_price > 0),
  currency              char(3)     NOT NULL,
  booked_at             date        NOT NULL,
  cancel_reason         text,
  unit_no               text        NOT NULL,
  unit_kind             text        NOT NULL,
  project_id            uuid        NOT NULL,
  project_name          text        NOT NULL,
  buyer_name            text        NOT NULL,
  buyer_phone           text,
  buyer_email           text,
  installments_total    int         NOT NULL DEFAULT 0,
  installments_paid     int         NOT NULL DEFAULT 0,
  installments_due      int         NOT NULL DEFAULT 0,
  installments_overdue  int         NOT NULL DEFAULT 0,
  installments_upcoming int         NOT NULL DEFAULT 0,
  received_amount       bigint      NOT NULL DEFAULT 0,
  pending_amount        bigint      NOT NULL DEFAULT 0,
  overdue_amount        bigint      NOT NULL DEFAULT 0,
  fine_amount           bigint      NOT NULL DEFAULT 0,
  next_due_date         date,
  escalated             boolean     NOT NULL DEFAULT false,
  summary_seq           int         NOT NULL DEFAULT 0,
  created_by            uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  version               int         NOT NULL DEFAULT 1
);
-- A unit has at most one live booking, so it can never be sold twice.
CREATE UNIQUE INDEX IF NOT EXISTS booking_unit_live_uq ON sales.booking (unit_id)
  WHERE status IN ('requested', 'confirmed', 'active', 'completed');
CREATE INDEX IF NOT EXISTS booking_status_idx ON sales.booking (tenant_id, status);
CREATE INDEX IF NOT EXISTS booking_customer_idx ON sales.booking (tenant_id, customer_id);
CREATE INDEX IF NOT EXISTS booking_project_idx ON sales.booking (tenant_id, project_id);
CREATE INDEX IF NOT EXISTS booking_page_idx ON sales.booking (tenant_id, booked_at DESC, id);

-- =============================================================================================
-- billing: invoices, payments, fines, escalations
-- =============================================================================================
CREATE TABLE IF NOT EXISTS billing.tenant_ref (
  tenant_id  uuid PRIMARY KEY,
  slug       text        NOT NULL,
  name       text        NOT NULL,
  currency   char(3)     NOT NULL,
  locale     text        NOT NULL,
  time_zone  text        NOT NULL,
  area_unit  text        NOT NULL,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS billing.project_ref (
  project_id uuid PRIMARY KEY,
  tenant_id  uuid        NOT NULL,
  name       text        NOT NULL,
  kind       text        NOT NULL,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_project_ref_idx ON billing.project_ref (tenant_id);

CREATE TABLE IF NOT EXISTS billing.unit_ref (
  unit_id      uuid PRIMARY KEY,
  tenant_id    uuid        NOT NULL,
  project_id   uuid        NOT NULL,
  project_name text        NOT NULL,
  unit_no      text        NOT NULL,
  kind         text        NOT NULL,
  status       text        NOT NULL,
  list_price   bigint      NOT NULL,
  currency     char(3)     NOT NULL,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_unit_ref_idx ON billing.unit_ref (tenant_id, project_id, kind);

CREATE TABLE IF NOT EXISTS billing.customer_ref (
  customer_id uuid PRIMARY KEY,
  tenant_id   uuid        NOT NULL,
  full_name   text        NOT NULL,
  phone       text,
  email       text,
  source_at    timestamptz NOT NULL DEFAULT '-infinity',  -- when the source event happened: stale events are ignored
  updated_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_customer_ref_idx ON billing.customer_ref (tenant_id);

CREATE TABLE IF NOT EXISTS billing.collection_setting (
  tenant_id         uuid PRIMARY KEY,
  grace_days        int         NOT NULL DEFAULT 5 CONSTRAINT setting_grace_chk CHECK (grace_days BETWEEN 0 AND 60),
  escalation_missed int         NOT NULL DEFAULT 3 CONSTRAINT setting_escalation_chk CHECK (escalation_missed >= 1),
  updated_by_name   text,
  updated_at        timestamptz NOT NULL DEFAULT now()
);

-- Per-tenant gap-free numbering (invoices, receipts, references): UPDATE ... RETURNING value.
CREATE TABLE IF NOT EXISTS billing.counter (
  tenant_id uuid   NOT NULL,
  name      text   NOT NULL,
  value     bigint NOT NULL DEFAULT 0 CONSTRAINT counter_value_chk CHECK (value >= 0),
  PRIMARY KEY (tenant_id, name)
);

CREATE TABLE IF NOT EXISTS billing.booking_ref (
  booking_id     uuid PRIMARY KEY,
  tenant_id      uuid        NOT NULL,
  customer_id    uuid        NOT NULL,
  customer_name  text        NOT NULL,
  customer_phone text,
  customer_email text,
  unit_id        uuid        NOT NULL,
  unit_no        text        NOT NULL,
  unit_kind      text        NOT NULL,
  project_id     uuid        NOT NULL,
  project_name   text        NOT NULL,
  total_price    bigint      NOT NULL,
  currency       char(3)     NOT NULL,
  plan_name      text        NOT NULL,
  status         text        NOT NULL DEFAULT 'active' CONSTRAINT billing_booking_status_chk CHECK (status IN
                   ('active', 'completed', 'cancelled')),
  booked_at      date        NOT NULL,
  summary_seq    int         NOT NULL DEFAULT 0,
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS billing_booking_customer_idx ON billing.booking_ref (tenant_id, customer_id);
CREATE INDEX IF NOT EXISTS billing_booking_project_idx ON billing.booking_ref (tenant_id, project_id);

CREATE TABLE IF NOT EXISTS billing.installment (
  id                uuid PRIMARY KEY,
  tenant_id         uuid        NOT NULL,
  booking_id        uuid        NOT NULL REFERENCES billing.booking_ref (booking_id) ON DELETE RESTRICT,
  seq               int         NOT NULL CONSTRAINT installment_seq_chk CHECK (seq >= 0),
  kind              text        NOT NULL CONSTRAINT installment_kind_chk CHECK (kind IN ('down_payment', 'emi')),
  invoice_no        text        NOT NULL,
  issued_on         date        NOT NULL,
  due_date          date        NOT NULL,
  amount            bigint      NOT NULL CONSTRAINT installment_amount_chk CHECK (amount > 0),
  original_amount   bigint      NOT NULL CONSTRAINT installment_original_chk CHECK (original_amount > 0),
  paid_amount       bigint      NOT NULL DEFAULT 0 CONSTRAINT installment_paid_chk CHECK (paid_amount >= 0),
  fine_amount       bigint      NOT NULL DEFAULT 0 CONSTRAINT installment_fine_chk CHECK (fine_amount >= 0),
  status            text        NOT NULL DEFAULT 'scheduled' CONSTRAINT installment_status_chk CHECK (status IN
                      ('scheduled', 'due', 'paid', 'overdue', 'waived', 'rescheduled', 'cancelled')),
  paid_at           timestamptz,
  method            text,
  payment_source    text        CONSTRAINT installment_source_chk CHECK (payment_source IS NULL OR payment_source IN ('manual', 'stripe')),
  received_on       date,
  payment_reference text,
  receipt_no        text,
  adjustment_reason text,
  -- snapshots so lists, fines and stats never join across services
  project_id        uuid        NOT NULL,
  customer_id       uuid        NOT NULL,
  unit_id           uuid        NOT NULL,
  unit_kind         text        NOT NULL,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),
  version           int         NOT NULL DEFAULT 1,
  CONSTRAINT installment_booking_seq_uq UNIQUE (booking_id, seq),
  CONSTRAINT installment_paid_within_amount_chk CHECK (paid_amount <= amount),
  CONSTRAINT installment_paid_state_chk CHECK (status <> 'paid' OR paid_amount = amount)
);
CREATE UNIQUE INDEX IF NOT EXISTS installment_invoice_no_uq ON billing.installment (tenant_id, invoice_no);
CREATE INDEX IF NOT EXISTS installment_status_due_idx ON billing.installment (tenant_id, status, due_date);
CREATE INDEX IF NOT EXISTS installment_customer_idx ON billing.installment (tenant_id, customer_id, due_date);
CREATE INDEX IF NOT EXISTS installment_project_idx ON billing.installment (tenant_id, project_id, status);
CREATE INDEX IF NOT EXISTS installment_unit_idx ON billing.installment (tenant_id, unit_id);
CREATE INDEX IF NOT EXISTS installment_booking_idx ON billing.installment (tenant_id, booking_id, seq);
CREATE INDEX IF NOT EXISTS installment_page_idx ON billing.installment (tenant_id, due_date, id);
-- the daily sweep touches only unpaid, still-moving invoices
CREATE INDEX IF NOT EXISTS installment_sweep_idx ON billing.installment (due_date) WHERE status IN ('scheduled', 'due');

CREATE TABLE IF NOT EXISTS billing.payment (
  id               uuid PRIMARY KEY,
  tenant_id        uuid        NOT NULL,
  installment_id   uuid        NOT NULL REFERENCES billing.installment (id) ON DELETE RESTRICT,
  booking_id       uuid        NOT NULL,
  amount           bigint      NOT NULL CONSTRAINT payment_amount_chk CHECK (amount > 0),
  method           text        NOT NULL CONSTRAINT payment_method_chk CHECK (method IN
                     ('cash', 'bank_transfer', 'online', 'cheque', 'card')),
  source           text        NOT NULL CONSTRAINT payment_source_chk CHECK (source IN ('manual', 'stripe')),
  reference        text        NOT NULL,
  received_on      date        NOT NULL,
  note             text,
  stripe_intent_id text,
  recorded_by      uuid,
  recorded_by_name text,
  created_at       timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT payment_card_chk CHECK ((source = 'stripe') = (stripe_intent_id IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS payment_reference_uq ON billing.payment (tenant_id, reference);
CREATE UNIQUE INDEX IF NOT EXISTS payment_intent_uq ON billing.payment (tenant_id, stripe_intent_id) WHERE stripe_intent_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS payment_installment_idx ON billing.payment (installment_id, created_at);
CREATE INDEX IF NOT EXISTS payment_booking_idx ON billing.payment (tenant_id, booking_id);

-- Card payments in flight. The stand-in provider keeps its state here; a real provider will hold it.
CREATE TABLE IF NOT EXISTS billing.payment_intent (
  id                uuid PRIMARY KEY,
  tenant_id         uuid        NOT NULL,
  installment_id    uuid        NOT NULL REFERENCES billing.installment (id) ON DELETE RESTRICT,
  provider_id       text        NOT NULL,
  client_secret     text        NOT NULL,
  amount            bigint      NOT NULL CONSTRAINT intent_amount_chk CHECK (amount > 0),
  currency          char(3)     NOT NULL,
  adjusted_amount   bigint,
  adjustment_reason text,
  status            text        NOT NULL DEFAULT 'requires_payment_method' CONSTRAINT intent_status_chk CHECK (status IN
                      ('requires_payment_method', 'succeeded')),
  charge_id         text,
  card_last4        text,
  recorded          boolean     NOT NULL DEFAULT false,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS intent_provider_uq ON billing.payment_intent (provider_id);
CREATE INDEX IF NOT EXISTS intent_installment_idx ON billing.payment_intent (tenant_id, installment_id);

CREATE TABLE IF NOT EXISTS billing.fine_rule (
  id              uuid PRIMARY KEY,
  tenant_id       uuid        NOT NULL,
  scope           text        NOT NULL CONSTRAINT fine_scope_chk CHECK (scope IN ('default', 'project', 'unit', 'customer')),
  scope_id        uuid,
  unit_kind       text        CONSTRAINT fine_unit_kind_chk CHECK (unit_kind IS NULL OR unit_kind IN ('plot', 'flat', 'villa', 'shop')),
  kind            text        NOT NULL CONSTRAINT fine_kind_chk CHECK (kind IN ('percent', 'fixed')),
  value           bigint      NOT NULL CONSTRAINT fine_value_chk CHECK (value >= 0),
  updated_by_name text,
  created_at      timestamptz NOT NULL DEFAULT now(),
  updated_at      timestamptz NOT NULL DEFAULT now(),
  version         int         NOT NULL DEFAULT 1,
  -- the default has no target; every other level needs one
  CONSTRAINT fine_scope_target_chk CHECK ((scope = 'default') = (scope_id IS NULL)),
  -- a single property has one category, so no category rate for it
  CONSTRAINT fine_unit_scope_chk CHECK (scope <> 'unit' OR unit_kind IS NULL),
  -- percentage is basis points, at most 100%
  CONSTRAINT fine_percent_chk CHECK (kind <> 'percent' OR value <= 10000)
);
-- one rate per level and category (NULLs collide through coalesce, so this works on PG 14 too)
CREATE UNIQUE INDEX IF NOT EXISTS fine_rule_level_uq ON billing.fine_rule
  (tenant_id, scope, coalesce(scope_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(unit_kind, ''));
CREATE INDEX IF NOT EXISTS fine_rule_lookup_idx ON billing.fine_rule (tenant_id, scope, scope_id);

-- A cancellation that arrives before its booking was ever scheduled (events can reorder): remembered
-- so that a late booking.confirmed does not create a schedule for a cancelled booking.
CREATE TABLE IF NOT EXISTS billing.cancelled_booking (
  booking_id   uuid PRIMARY KEY,
  tenant_id    uuid        NOT NULL,
  cancelled_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS billing.escalation_notice (
  booking_id   uuid PRIMARY KEY REFERENCES billing.booking_ref (booking_id) ON DELETE RESTRICT,
  tenant_id    uuid        NOT NULL,
  sent_at      timestamptz NOT NULL,
  sent_by      uuid,
  sent_by_name text
);
CREATE INDEX IF NOT EXISTS escalation_notice_tenant_idx ON billing.escalation_notice (tenant_id);

-- =============================================================================================
-- contract: contracts and versions
-- =============================================================================================
CREATE TABLE IF NOT EXISTS contract.booking_ref (
  booking_id     uuid PRIMARY KEY,
  tenant_id      uuid        NOT NULL,
  customer_id    uuid        NOT NULL,
  customer_name  text        NOT NULL,
  customer_email text,
  unit_no        text        NOT NULL,
  cancelled      boolean     NOT NULL DEFAULT false,
  updated_at     timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS contract_booking_ref_idx ON contract.booking_ref (tenant_id);

CREATE TABLE IF NOT EXISTS contract.contract (
  id                   uuid PRIMARY KEY,
  tenant_id            uuid        NOT NULL,
  booking_id           uuid        NOT NULL REFERENCES contract.booking_ref (booking_id) ON DELETE RESTRICT,
  kind                 text        NOT NULL CONSTRAINT contract_kind_chk CHECK (kind IN ('signed_upload', 'pandadoc')),
  title                text        NOT NULL,
  template             text        CONSTRAINT contract_template_chk CHECK (template IS NULL OR template IN
                         ('sale_agreement', 'payment_plan_addendum')),
  status               text        NOT NULL CONSTRAINT contract_status_chk CHECK (status IN
                         ('draft', 'sent', 'viewed', 'signed', 'declined', 'voided')),
  version              int         NOT NULL CONSTRAINT contract_version_chk CHECK (version >= 1),
  supersedes_id        uuid        REFERENCES contract.contract (id) ON DELETE RESTRICT,
  revision_note        text,
  file_key             text,
  file_name            text,
  file_size            bigint      CONSTRAINT contract_file_size_chk CHECK (file_size IS NULL OR file_size BETWEEN 1 AND 10485760),
  content_type         text,
  provider_document_id text,
  signer_email         text,
  sent_at              timestamptz,
  signed_at            timestamptz,
  created_by_name      text,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  version_lock         int         NOT NULL DEFAULT 1,
  CONSTRAINT contract_booking_version_uq UNIQUE (booking_id, version),
  -- an uploaded copy is signed from the start and always has its file
  CONSTRAINT contract_upload_chk CHECK (kind <> 'signed_upload' OR
    (file_key IS NOT NULL AND file_size IS NOT NULL AND status IN ('signed', 'voided'))),
  -- a PandaDoc contract has no uploaded file and no revision of itself
  CONSTRAINT contract_pandadoc_chk CHECK (kind <> 'pandadoc' OR file_key IS NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS contract_one_signed_uq ON contract.contract (booking_id) WHERE status = 'signed';
CREATE UNIQUE INDEX IF NOT EXISTS contract_one_open_uq ON contract.contract (booking_id)
  WHERE kind = 'pandadoc' AND status IN ('draft', 'sent', 'viewed', 'declined');
CREATE INDEX IF NOT EXISTS contract_booking_idx ON contract.contract (tenant_id, booking_id, version DESC);

